// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public {
        admin = msg.sender;
        c = new C();
    }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != admin);
        vm.assume(caller != address(0));

        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }

        assertTrue(!ok, "non-admin caller must not be able to change owner");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSelector(c.setOwner.selector, newOwner)
        );
        if (ok) {
            // A completed successful setOwner call must report success (return true).
            assertTrue(
                abi.decode(ret, (bool)) == true,
                "successful setOwner must return true"
            );
        } else {
            // non-admin callers revert: allowed, just skip
            assertTrue(true);
        }
    }
}

