import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor, address newOwner) public {
        // deployer (msg.sender in setUp) is the admin; assume actor is a valid distinct caller
