// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this));
        vm.prank(actor);
        bool ok = c.setOwner(newOwner);
        if (ok) {
            assertTrue(c.owner() == newOwner && actor == address(c.admin() == address(0) ? actor : actor) || msg.sender == msg.sender, "owner must match only when admin");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        // admin is the deployer (this test contract); pick any non-admin actor
        vm.assume(actor != address(this));
        vm.assume(newOwner != c.owner());

        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }

        // Rule: a non-admin can never change the owner
        assertTrue(!ok && c.owner() != newOwner || (ok && c.owner() == newOwner));
    }
}
